import React, { useEffect, useState, useRef } from "react";
import { GoogleMap, Marker, LoadScript, DirectionsRenderer } from "@react-google-maps/api";
import { useParams, useNavigate } from "react-router-dom";
import axios from "axios";
import io from "socket.io-client";

const socket = io("http://localhost:5000");

const containerStyle = {
  width: "100%",
  height: "600px",
};

const API_BASE_URL = process.env.REACT_APP_API_URL || "http://localhost:5000";

export default function TrackDeliveryPage() {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const [location, setLocation] = useState<{ lat: number; lng: number } | null>(null);
  const [destination, setDestination] = useState<{ lat: number; lng: number } | null>(null);
  const [directions, setDirections] = useState<google.maps.DirectionsResult | null>(null);

  const mapRef = useRef<google.maps.Map>();

  // Fetch delivery info
  useEffect(() => {
    if (!id) return;

    axios.get(`${API_BASE_URL}/api/delivery/${id}`).then((res) => {
      const delivery = res.data;
      setDestination(delivery.location);
      setLocation(delivery.location); // start at delivery point initially

      // Start socket tracking
      socket.emit("trackDelivery", id);

      socket.on("locationUpdate", (newLocation: { lat: number; lng: number }) => {
        setLocation(newLocation);
      });
    });
  }, [id]);

  // Calculate route whenever location or destination changes
  useEffect(() => {
    if (!location || !destination) return;

    const directionsService = new google.maps.DirectionsService();
    directionsService.route(
      {
        origin: location,
        destination: destination,
        travelMode: google.maps.TravelMode.DRIVING,
      },
      (result, status) => {
        if (status === google.maps.DirectionsStatus.OK && result) {
          setDirections(result);
        } else {
          console.error("❌ Directions request failed:", status);
        }
      }
    );
  }, [location, destination]);

  return (
    <div style={{ padding: "20px" }}>
      <h2>🚚 Tracking Delivery</h2>
      <LoadScript googleMapsApiKey={process.env.REACT_APP_GOOGLE_MAPS_API_KEY!}>
        <GoogleMap
          mapContainerStyle={containerStyle}
          center={location || destination || { lat: 6.9271, lng: 79.8612 }}
          zoom={13}
          onLoad={(map) => {
            mapRef.current = map;
          }}
          
        >
          {location && <Marker position={location} label="Driver" />}
          {destination && <Marker position={destination} label="Destination" />}
          {directions && <DirectionsRenderer directions={directions} />}
        </GoogleMap>
      </LoadScript>

      <button
        onClick={() => navigate("/")}
        style={{
          marginTop: "20px",
          padding: "10px 20px",
          backgroundColor: "#6c757d",
          color: "#fff",
          border: "none",
          borderRadius: "4px",
        }}
      >
        ← Back to Dashboard
      </button>
    </div>
  );
}
